import assert from 'node:assert';
import { clearUserCache, loadUser } from './users.js';

test('loadUser returns cached users', async () => {
  clearUserCache();
  let calls = 0;
  const fetcher = async (id) => ({ id, calls: ++calls });
  assert.deepStrictEqual(await loadUser('ada', fetcher), { id: 'ada', calls: 1 });
  assert.deepStrictEqual(await loadUser('ada', fetcher), { id: 'ada', calls: 1 });
  assert.strictEqual(calls, 1);
});

